// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will become the owner via NETM
    function testFuzz_property(address newOwner) public {
        // keep address non-zero to be meaningful
        vm.assume(newOwner != address(0));

        // ensure caller is the current owner (constructor set owner = msg.sender in C, which is this test contract)
        // NETM is onlyOwner, so we must call as current owner. The test contract is the owner because it deployed c in setUp().

        // call NETM as the owner but with msg.sender set to this test contract (already true)
        // The NETM function sets owner = msg.sender (keeps owner as this test contract) in both versions,
        // but in the reference it also credits balances[owner] = totalDistributed. To transfer ownership to newOwner,
        // we use transferOwnership afterwards to set the owner to newOwner to observe balances at that address.

        // First, call NETM() (this is onlyOwner, allowed since this test contract deployed c)
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }
        // NETM should not revert on the reference; still, we don't assert on ok because both versions execute NETM.

        // Now transfer ownership to a chosen address so that we can check balances[newOwner]
        // transferOwnership requires onlyOwner, so call it as current owner (this test contract)
        c.transferOwnership(newOwner);

        // The invariant we assert: in the reference, the owner's balance equals totalDistributed.
        // We read balances via the public getter balanceOf(newOwner), and totalDistributed via public variable.
        uint256 ownerBalance = c.balanceOf(newOwner);
        uint256 totalDistributed = c.totalDistributed();

        // Single assertion: reference satisfies balances[owner] == totalDistributed for any newOwner;
        // the mutant that omits crediting balances will fail for at least some newOwner (specifically the owner that should have been credited).
        assertTrue(ownerBalance == totalDistributed);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address to become the new owner; we must ensure caller is owner in order to call NETM()
    // so we will first transfer ownership to the fuzzed address by calling transferOwnership from the initial owner
    // The general property: after NETM() is called by the owner, balances[owner] == totalDistributed.
    function testFuzz_property(address newOwner) public {
        // keep newOwner within normal address space (exclude zero to be meaningful)
        vm.assume(newOwner != address(0));

        // initial owner is the deployer, which is the test contract's address when creating C via new C()
        // However in this setup owner was set to msg.sender at construction (setUp called from this contract), so
        // the test contract is the owner. We need to make newOwner the caller of NETM(), so transfer ownership.

        // transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // now call NETM() as newOwner
        vm.prank(newOwner);
        // Use try/catch to capture possible revert but NETM is onlyOwner, so should succeed
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the reference: after NETM by the owner, balances[owner] == totalDistributed
        // We observe via public getters: c.owner() does not exist (owner is private), but NETM sets owner = msg.sender
        // and there is no getter for owner; however the behavior we can read is balances[newOwner] equals totalDistributed.
        // totalDistributed is public, and balanceOf is public.

        uint256 td = c.totalDistributed();
        uint256 bal = c.balanceOf(newOwner);

        // Single assertion: in the correct contract, calling NETM() as owner results in balances[newOwner] == totalDistributed.
        // The mutant that assigns balances to the previous owner will make this assertion fail for some newOwner.
        assertTrue(ok && bal == td);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller who will be the owner when calling NETM
    function testFuzz_property(address newOwner) public {
        // keep newOwner non-zero to be a sensible owner candidate
        vm.assume(newOwner != address(0));

        // The contract's constructor set owner = msg.sender (the test contract),
        // but NETM is protected by onlyOwner. To test the behavior when an
        // arbitrary address becomes owner and then calls NETM, we first
        // transfer ownership to newOwner by calling transferOwnership from the
        // current owner (this contract). That models the general situation
        // where some owner calls NETM.

        // ensure this contract is the current owner (it is, as setUp used new C())
        // now transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // Now impersonate newOwner and call NETM(). NETM() in reference sets
        // owner = msg.sender and balances[owner] = totalDistributed (in that
        // order). The invariant we assert: after NETM, balances[ owner() ] == totalDistributed.
        vm.prank(newOwner);
        c.NETM();

        // single assertion: reference must always hold this; mutant (which
        // writes balances[oldOwner] = totalDistributed before updating owner)
        // will fail for some newOwner choices (specifically any newOwner != test contract),
        // so the fuzzer can find a counterexample.
        assertTrue(c.balanceOf(c.owner()) == c.totalDistributed());
    }
}
